    "keyName": {
      "sourceKey": "Spell_YuumiHugCast_Name",
      "text": "悠米出动！"
    },
    "keySummary": {
      "sourceKey": "Spell_YuumiHugCast_Summary",
      "text": "悠米突进到一名目标友方英雄处，变得不可被选取（防御塔除外）。在附身于她的挚友身上时，她会获得治疗与护盾强度并为她的这名友军提供附加治疗效果。"
    },
    "keyTooltip": {
      "sourceKey": "Spell_YuumiHugCast_Tooltip",
      "text": "<spellPassive>被动：</spellPassive>在附身于她的<keywordMajor>挚友</keywordMajor>身上时，悠米获得额外的<keywordMajor>@HealAndShieldPower*100@%治疗与护盾强度</keywordMajor>并且她的这名友军也会获得<OnHit>附加%i:OnHit%</OnHit><healing>@HealthOnHit@治疗效果</healing>。<br><br><spellActive>主动：</spellActive>悠米突进到一名目标友方英雄处，并<keywordMajor>附身</keywordMajor>到该友军身上。当悠米处于<keywordMajor>附身</keywordMajor>状态时，她会跟随她搭档的移动并且不可被选取（防御塔除外）。<br><br>对悠米施加<status>定身</status>效果会使这个技能进入为期@CCAttachLockout@秒的冷却时间。"
    },
    "keyCooldown": {
      "sourceKey": "Spell_YuumiW_Cooldown",
      "text": "@AttachCooldown@秒%i:cooldown%"
    },
    "keyTooltipExtendedBelowLine": {
      "sourceKey": "Spell_YuumiW_TooltipExtendedBelowLine",
      "text": "<rules>这个技能拥有@spell.YuumiW:AttachCooldown@秒冷却时间，但悠米在准备就绪时，可以随时切换<keywordMajor>附身</keywordMajor>的队友，或是<keywordMajor>解除附身</keywordMajor>。<br><br>悠米的技能将使用她<keywordMajor>附身</keywordMajor>友军的位置，而非她自身的。<br><br>悠米将在该友军使用召唤师技能【传送】时<keywordMajor>解除附身</keywordMajor>。</rules>"
    },
    "keyCost": {
      "sourceKey": "Spell_Cost_NoCost",
      "text": "无消耗"
    }
  }
